  const AV_CORES = ['#3C659B','#2F6FB5','#6BAAC9','#C2000C','#550E0B','#4F8CB8'];
  const corDe = (txt) => { let h = 0; for (const c of norm(txt)) h = (h * 31 + c.charCodeAt(0)) >>> 0; return AV_CORES[h % AV_CORES.length]; };
