    return `<div class="tl-card"><div class="tl-inner" data-de="${ymd(from)}" data-span="${span}">${head}${corpo}<div class="tl-regua" aria-hidden="true"><span></span></div></div></div><div class="tl-foot">${legenda}${toggle}</div>`;
