  const FN_ROT = { 'Ativo': ['ativo', 'ativos'], 'Férias': ['em férias', 'em férias'], 'Afastado': ['afastado', 'afastados'], 'Inativo': ['inativo', 'inativos'], 'Desligado': ['desligado', 'desligados'] };
  const FUNC_PAG = 48, FUNC_MAX_BUSCA = 40;
