    return `${titulo.replace('@@BUSCA@@', busca)}${note ? `<div class="dp-sec-note${fn ? ' fn-fonte' : ''}">${note}</div>` : ''}<div class="dp-section-rows">${rows || `<div class="empty-mini">${fn ? 'Nenhum funcionário ativo.' : 'Nenhum registro.'}</div>`}</div>${addRow}`;
