      if (todosOcultos && !sem) { sem = document.createElement('div'); sem.className = 'empty-mini fn-sem'; sem.textContent = 'Nenhum funcionário encontrado.'; c.appendChild(sem); }
      if (sem) sem.hidden = !todosOcultos;
