    if (dup) { const ok = await ask(`Já existe uma empresa com este CNPJ: “${dup.nome}”.\nCriar mesmo assim?`, [{label:'Voltar',value:false},{label:'Criar mesmo assim',value:true}]); if (!ok) return; }
    dpDraft = false;
