    await cvAcompMudar(l => l.map(x => x.id === id ? { ...x, achada: null, ignorados: [...x.ignorados, ...regs] } : x));
    toast('Ignorada: a busca diária não vai trazê-la de novo.'); cvRenderSeAberto();
