        const p = x.ef.pisos.val[0]; piso = p ? `<b>${escapeHtml(moeda(p.valor))}</b>${x.ef.pisos.val.length > 1 ? `<small>+${x.ef.pisos.val.length - 1}</small>` : ''}` : (x.sug ? '<span class="cvs-conferir">conferir</span>' : '<span class="dp-cell-sub">—</span>');
