    ovRoster().semEmp.forEach(g => { const a = m.get(g.k); if (a) { a.nEmp += g.nEmp; if (!a.cod && g.cod) a.cod = g.cod; } else m.set(g.k, { k: g.k, cod: g.cod, cli: g.cli, n: 0, nEmp: g.nEmp, cand: g.cand }); });
