    const ix = new Map(); m.forEach((v, k) => { const vi = v.vinculos || {}; Object.keys(vi).forEach(mod => (Array.isArray(vi[mod]) ? vi[mod] : []).forEach(id => { if (!ix.has(mod + '|' + id)) ix.set(mod + '|' + id, k); })); });
