  document.addEventListener('click', (e) => { const b = e.target.closest && e.target.closest('[data-cad-abrir]'); if (!b) return; e.preventDefault(); if (dlgDetail.open) dlgDetail.close(); cadAbrir(b.dataset.cadAbrir, b.dataset.id); });
