    const g = ovSemVinc().find(x => x.k === k); if (!g) return { ok: false, erro: 'Esse cliente já foi ligado a uma empresa.' };
    const cl = ovClientes().get(g.cod) || null, nome = String((cl && cl.nome) || g.cli || '').replace(/\s*\|\s*\d{4}-\d{2}\s*$/, '').trim().slice(0, 140);
