    if (m.cortado) return rot + ' veio incompleta no último envio';
    if (Date.now() - (Number(m.recebidoEm) || 0) > GT_VALIDO_H * 3600e3) return rot + ' tem mais de ' + GT_VALIDO_H + ' horas';
    if (!gtCarregado(t)) { gtLer(t); return 'carregando'; }
